/* Generated by scripts/postinstall.mjs — do not edit by hand. */
const CACHE_VERSION = '1.0.0';
const CONTENT_CACHE = `onyx-observer-content-${CACHE_VERSION}`;

self.addEventListener('install', (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key !== CONTENT_CACHE).map((key) => caches.delete(key))),
      )
      .then(() => self.clients.claim()),
  );
});

/* Static app-shell assets are hash-named by Vite, so a cache-first
 * strategy is safe there. Observer projections under /api are live data:
 * network-first, falling back to the last successful snapshot only when
 * offline — stale observer data shown with the offline banner is better
 * than nothing, but it must never win over fresh data. */
const apiRequest = (request) =>
  new URL(request.url).pathname.startsWith('/api/');

async function networkFirst(request) {
  try {
    const response = await fetch(request);
    if (response && response.ok) {
      const clone = response.clone();
      const cache = await caches.open(CONTENT_CACHE);
      await cache.put(request, clone);
    }
    return response;
  } catch {
    return (await caches.match(request)) || Response.error();
  }
}

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;
  return fetch(request);
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  if (new URL(request.url).origin !== self.location.origin) return;
  event.respondWith(apiRequest(request) ? networkFirst(request) : cacheFirst(request));
});

/* Phase 3.2: display and route notifications. */
self.addEventListener('push', (event) => {
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    payload = {};
  }
  const title = typeof payload.title === 'string' ? payload.title : 'ONYX Observer';
  const options = {
    body: typeof payload.message === 'string' ? payload.message : '',
    icon: '/icons/icon.svg',
    badge: '/icons/icon.svg',
    data: typeof payload.url === 'string' ? payload.url : '/notifications',
  };
  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil(
    self.clients
      .matchAll({ type: 'window', includeUncontrolled: true })
      .then(async (clients) => {
        const target = event.notification.data || '/';
        const client = clients.find((c) => 'focus' in c && 'navigate' in c);
        if (client) {
          try {
            await client.navigate(target);
            return client.focus();
          } catch {
            /* fall through to a fresh window */
          }
        }
        return self.clients.openWindow(target);
      }),
  );
});